"""Verify the packaged VM against its pinned sources and generated bytes."""
from pathlib import Path
import hashlib
import json

ROOT = Path(__file__).resolve().parents[1]

def manifest():
    paths = [*sorted((ROOT / 'vm/src').glob('*.rs')),
             *[ROOT / 'vm' / name for name in ['Cargo.toml', 'Cargo.lock', 'prelude.lua', 'piccolo-checkpoint.patch', '.cargo/config.toml']],
             *sorted((ROOT / 'scripts').glob('*.py')), ROOT / 'generated/kernel.wasm']
    return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest() for path in paths}

if __name__ == '__main__':
    if json.loads((ROOT / 'generated/manifest.json').read_text()) != manifest():
        raise SystemExit('Lua VM inputs or assets changed; run pnpm wasm:build')
    print('Lua VM source and artifact hashes verified')
